head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil22110";
scwin.successCnt = 0;
scwin.resultCnt = 0;
scwin.totalFileCnt = 0;
scwin.result = null;
scwin.apiUrl = undefined;
scwin.failArr = undefined;
scwin.urlInfo = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_contn", attr: "label", fn: function () { return String(dma_consultVO.get("quesContn")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_25", entity: "dlt_realInvstgMajContnList", countIds: [], cells: [{ childId: "ipt_realInvstgMajContnCd", fn: function (v, i) { return String(v("realinvstgmajcontncd")); } }, { childId: "__rc0", fn: function (v, i) { return " " + String(v("realinvstgmajcontnnm")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_apiYn", fn: function () { return String(String((dma_pageContext.get("apiYn") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
        scwin.setLength($('#quesContn').val(), 'quesContnCharNum', '4000');
        // as-is jQuery UI tooltip 호출 제거 — 컴포넌트 toolTip 속성으로(퍼블리싱 확인)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22110.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.apiUrl =urlInfo(); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil22110' }); }

try { scwin.failArr =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil22110' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.urlInfo = urlInfo;
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil22110.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22110.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22110.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name realInvstgDataForm_onsubmit
