 * @returns {void}
 * @hidden N
 */
scwin.realInvstgDataForm_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22110.realInvstgDataForm_onsubmit' }); }
};

/**
 * @method
 * @name txa_contn_onkeyup
 * @description txa_contn 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txa_contn_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.setLength(selfVar.value, 'quesContnCharNum', '4000');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22110.txa_contn_onkeyup' }); }
};

/**
 * @method
 * @name txa_contn_onblur
 * @description txa_contn 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_contn_onblur = async function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        await scwin.estimateCounter(selfVar, '4000');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22110.txa_contn_onblur' }); }
};

/**
 * @method
 * @name button_46_onclick
