        await scwin.fnFileMinus()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22110.button_47_onclick' }); }
};

/**
 * @method
 * @name registerBtn_onclick
 * @description 「자료 제출」 클릭 이벤트
 * @param {Object} e 이벤트 객체
