///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name fileSize
 * @description file Size 처리
 * @param {Number} idx idx
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSize = async function (idx) {
    const yn = $c.util.getComponent('ipt_apiYn').getValue();
    const fSize = scwin.fileSizeChk($c.util.getComponent("attachUploadFile" + (idx)).files[0].size);
    if (fSize > 0) {
        if (yn === 'Y') {
            await $c.win.alert('첨부파일의 용량은 개당 100MB를 넘을수 없습니다.');
        } else {
            await $c.win.alert('첨부파일의 용량은 개당 30MB를 넘을수 없습니다.');
        }
        $c.util.getComponent("attachUploadFile" + (idx)).setValue("");
        return false;
    }
};

function urlInfo() {
    let returnUrl = '';
    const url = location.host;
    if (url === ('localhost:8081') || url === ('idev-filing.krx.co.kr')) {
        returnUrl = 'https://idev-kind-api.krx.co.kr';
    } else {
        if (url === ('dev-filing.krx.co.kr')) {
            returnUrl = 'https://dev-kind-api.krx.co.kr';
        } else {
            if (url === ('test-filing.krx.co.kr')) {
                returnUrl = 'https://test-kind-api.krx.co.kr';
            } else {
                if (url === ('filing.krx.co.kr')) {
                    returnUrl = 'https://kind-api.krx.co.kr';
                } else {
                    if (url === ('dr-filing.krx.co.kr')) {
                        returnUrl = 'https://dr-kind-api.krx.co.kr';
                    }
                }
            }
        }
    }
    return returnUrl;
}

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.list = async function () {
    $c.util.getComponent('ipt_method').setValue("disclsConsultApplList");
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#disclsConsultForm').attr("action", "disclsConsult.do");
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#disclsConsultForm').attr("onsubmit", "");
    const nr = await scwin.tx_fn_list();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil11000/jldfil11000.xml");
    }
};

/**
 * @method
 * @name fnFilePlus
 * @description fn File Plus 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnFilePlus = function () { $c.util.onUploadClick($c.util.getComponent('mpd_files')); };

/**
 * @method
 * @name fnFileMinus
 * @description fn File Minus 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnFileMinus = async function () { if (typeof scwin.btn_mpd_files_del_onclick === 'function') { await scwin.btn_mpd_files_del_onclick(); } };

/**
 * @method
 * @name setLength
 * @description set Length 처리
 * @param {Object} obj 컴포넌트
 * @param {*} tdName tdName
 * @param {*} maxLength maxLength
 * @returns {void}
 * @hidden N
 */
scwin.setLength = function (obj, tdName, maxLength) {
    const strLength = scwin.calBytes(obj);
    ($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setValue) ? $c.util.getComponent(tdName).setValue("(" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setText) ? $c.util.getComponent(tdName).setText("(" + strLength + "/" + maxLength + ")") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdName), void ("(" + strLength + "/" + maxLength + ")")));
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @param {*} maxLength maxLength
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj, maxLength) {
    if (scwin.calBytes(obj.value) > maxLength) {
        await $c.win.alert('한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

/**
 * @method
 * @name validation
 * @description validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validation = async function () {
    let boxCnt = 0;
    // TODO Stage2(규칙 19): jQuery — 라디오/체크 그룹 → 퍼블리싱 그룹 컴포넌트 getValue/setValue
    $("input[name=realInvstgMajContnCd]:checked").each(function(index, item) {
            boxCnt++;
    });
    if (($c.util.getComponent('ipt_title').getValue() == null ? '' : String($c.util.getComponent('ipt_title').getValue())) === '' || $c.util.getComponent('ipt_title').getValue() == null) {
        await $c.win.alert("제목을 작성하세요.");
        return false;
    }
    if (boxCnt === 0) {
        await $c.win.alert("주요내용을 선택해 주세요.");
        return false;
    }
    if (($c.util.getComponent('slc_realInvstgStepCd').getValue() == null ? '' : String($c.util.getComponent('slc_realInvstgStepCd').getValue())) === '') {
        await $c.win.alert("진행단계를 선택하세요.");
        return false;
    }
    if (($c.util.getComponent('txa_contn').getValue() == null ? '' : String($c.util.getComponent('txa_contn').getValue())) === '' || $c.util.getComponent('txa_contn').getValue() == null) {
        await $c.win.alert("비고를 작성하세요.");
        return false;
    }
    if (scwin.calBytes($c.util.getComponent('txa_contn').getValue()) > 4000) {
        await $c.win.alert("비고는 한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.");
        return false;
    }
    return true;
};

/**
 * @method
 * @name fileValidation
 * @description file Validation 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileValidation = async function () {
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const file = $("input[type='file']");
    let fCnt = 0;
    let fNmLength = 0;
    let fType = 0;
    let fSize = 0;
    for (let i = 0; i < file.length; i++) {
        if (file.eq(i).attr("value") !== '' && file.eq(i).attr("value") != null) {
            fCnt++;
            fNmLength += scwin.fileNmLengthChk(file.eq(i).attr("value"));
            fType += scwin.fileTypeChk(file.eq(i).attr("value"));
            fSize += scwin.fileSizeChk($c.util.getComponent("attachUploadFile" + (i + 1)).files[0].size);
        }
    }
    if (fNmLength > 0) {
        await $c.win.alert('파일명 길이가 80byte 초과된 파일이 ' + fNmLength + '개 있습니다.');
        return false;
    }
    if (fType > 0) {
        await $c.win.alert('첨부할 수 없는 확장자를 가지 파일이 ' + fType + '개 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
        return false;
    }
    if (fSize > 0) {
        await $c.win.alert('첨부파일의 용량은 개당 100MB를 넘을수 없습니다.');
        return false;
    }
    return true;
};

/**
 * @method
 * @name fileTypeChk
 * @description file Type Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fileTypeChk = function (val) {
    const isFileType = ["DRT", "bmp", "gif", "jpeg", "jpg", "png", "hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf", "zip", "txt"];
    const fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();
    let returnVal = 0;
    let typeChkCnt = 0;
    for (i = 0; i < isFileType.length; i++) {
        if (isFileType[i] === fileType) {
            typeChkCnt++;
        }
    }
    if (typeChkCnt === 0) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
 * @name fileSizeChk
 * @description file Size Chk 처리
 * @param {*} fileSize fileSize
 * @returns {void}
 * @hidden N
 */
scwin.fileSizeChk = function (fileSize) {
    let mSize = 100;
    if ($c.util.getComponent('ipt_apiYn').getValue() === "N") {
        mSize = 30;
    }
    if (fileSize > (1024 * 1024 * mSize)) {
        return 1;
    }
    return 0;
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    if (!await scwin.validation()) {
        return false;
    }
    if (!await scwin.fileValidation()) {
        return false;
    }
    scwin.showSpinner();
    if (!await $c.win.confirm('저장하시겠습니까? 저장후에는 수정이 불가능 합니다')) {
        scwin.hideSpinner();
        return;
    }
    if (await scwin.getRealInvstgProcsNo()) {
        // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
        $.each($('[type=file]'), function(i, item) {
                // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
                const f = $(item)[0].files[0];
                if (f == null || f === '') {
                    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                    let idNum = $(item)[0].id;
                    idNum = idNum.replace('attachUploadFile', '');
                    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
                    $('#fileDiv' + idNum).remove();
                }
        });
        // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
        if ($c.util.getComponent('ipt_apiYn').getValue() === "Y" && $('[type=file]').length !== 0) {
            await scwin.apiFileUpload();
        } else {
            await scwin.formSubmit();
        }
    }
};

/**
 * @method
 * @name formSubmit
 * @description form Submit 처리
 * @returns {Promise<void>}
