 */
scwin.formSubmit = async function () {
    const frm = (document.realInvstgDataForm || { elements: [] });
    $c.util.getComponent('ipt_method').setValue("insertRealInvstg");
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#realInvstgDataForm').attr("action", "realInvstg.do");
    // TODO Stage2(규칙 19): jQuery — 폼 제출 → $c.sbm 서브미션(규칙 6, B-4 제출 주소 회신)
    $('#realInvstgDataForm').attr("onsubmit", "");
    await scwin.tx_fn_formSubmit();
};

/**
 * @method
 * @name fileNmLengthChk
 * @description file Nm Length Chk 처리
 * @param {*} val val
 * @returns {void}
 * @hidden N
 */
scwin.fileNmLengthChk = function (val) {
    const fVal = val.split("\\");
    const fNm = fVal[fVal.length - 1];
    let returnVal = 0;
    if (scwin.calBytes(fNm) > 80) {
        returnVal = 1;
    }
    return returnVal;
};

/**
 * @method
