 */
scwin.showSpinner = function () {
    document.getElementsByClassName('layerPopup')[0].style.display = 'block';
};

/**
 * @method
 * @name hideSpinner
 * @description hide Spinner 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideSpinner = function () {
    document.getElementsByClassName('layerPopup')[0].style.display = 'none';
};

/**
 * @method
 * @name apiFileUpload
 * @description api File Upload 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.apiFileUpload = async function () {
    let bl = false;
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const all_files = $('[type=file]');
    if (all_files.length > 0) {
        $.each(all_files, function(i, item) {
                // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
                const f = $(item)[0].files[0];
                if (f == null || f === '') {
                    // TODO Stage2(규칙 19): jQuery — 퍼블리싱 컴포넌트 참조로 재작성(B-7)
                    let idNum = $(item)[0].id;
                    idNum = idNum.replace('attachUploadFile', '');
                    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
                    $('#fileDiv' + idNum).remove();
                }
        });
    } else {
        return true;
    }
    const oData = await scwin.getOtherData();
    if (oData === '' || oData == null || oData === 'undefined') {
        void('apiKey 조회에 실패');
        return bl;
    }
    const arr = oData.split('||');
    const apiUrl = urlInfo();
    // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
    const attach_files = $('[type=file]');
    const errCnt = attach_files.length;
    if (attach_files.length > 0) {
        scwin.successCnt = 0;
        scwin.failArr = [];
        scwin.resultCnt = 0;
        scwin.totalFileCnt = attach_files.length;
        $.each(attach_files, function(i, item) {
                const formData = new FormData();
                // TODO Stage2(규칙 19): jQuery — 파일 입력 → w2:upload 컴포넌트 재설계(퍼블리싱 확인)
                formData.append("attachFile", $(item)[0].files[0]);
                formData.append("integUsrId", arr[1]);
                const bzProcsNo = $c.util.getComponent('ipt_bzProcsNo').getValue();
                const seq = i + 1;
                $.ajax({ url: apiUrl + "/auth/s1/listing/real-investigation/file-upload/" + bzProcsNo + "/" + seq, type: "POST", data: formData, processData: false, contentType: false, async: true, headers: { "apiKey": arr[0] }, success: async function(response) {
                            void('success : ' + response);
                            await scwin.apiSuccess(seq);
                        }, error: async function(request) {
                            void('error : ' + request);
                            await scwin.apiFail(formData, bzProcsNo, seq);
                        } });
        });
    }
    if (errCnt === 0) {
        bl = true;
    } else {
        bl = false;
    }
    return bl;
};

/**
 * @method
 * @name execResultCnt
 * @description exec Result Cnt 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.execResultCnt = async function (type) {
    scwin.resultCnt++;
    if (scwin.totalFileCnt === scwin.resultCnt) {
        if (type === "F") {
            const failTxt = "";
            for (i in scwin.failArr) {

            }
            if (!await $c.win.confirm('첨부파일 업로드 오류 입니다. 재시도 하시겠습니까?')) {
                scwin.hideSpinner();
                return;
            }
            await scwin.apiFileUpload();
        }
    }
};

/**
 * @method
 * @name apiFail
 * @description api Fail 처리
 * @param {*} formData formData
 * @param {*} bzProcsNo bzProcsNo
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.apiFail = async function (formData, bzProcsNo, seq) {
    await scwin.execResultCnt("F");
};

/**
 * @method
 * @name apiSuccess
 * @description api Success 처리
 * @param {*} seq seq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.apiSuccess = async function (seq) {
    // TODO Stage2(규칙 19): jQuery — DOM 조립/삭제 → 컴포넌트 setValue/DataList/그리드
    $('#fileDiv' + seq).remove();
    scwin.successCnt++;
    if (scwin.successCnt === scwin.totalFileCnt) {
        await scwin.formSubmit();
    }
    await scwin.execResultCnt("S");
};

