/**
 * @method
 * @name getRealInvstgProcsNoDone
 * @description get Real Invstg Procs No Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getRealInvstgProcsNoDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    if (scwin.result.realInvstgProcsNo !== '' && scwin.result.realInvstgProcsNo != null) {
        $c.util.getComponent('ipt_bzProcsNo').setValue(scwin.result.realInvstgProcsNo);
        bl = true;
    }
};

/**
 * @method
 * @name getRealInvstgProcsNo
 * @description get Real Invstg Procs No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getRealInvstgProcsNo = async function () {
    const r = await scwin.tx_fn_getRealInvstgProcsNo();
    try {
        scwin.getRealInvstgProcsNoDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil22110.fn_getRealInvstgProcsNo' });
    }
    return r;
};

/**
 * @method
 * @name getOtherDataDone
 * @description get Other Data Done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.getOtherDataDone = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    otherData = scwin.result.apiKey + '||' + scwin.result.integUsrId;
};

/**
 * @method
 * @name getOtherData
 * @description get Other Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getOtherData = async function () {
    const r = await scwin.tx_fn_getOtherData();
    try {
        scwin.getOtherDataDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil22110.fn_getOtherData' });
    }
    return r;
};
